import { Component, Input, Output, EventEmitter, ChangeDetectorRef, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { NgClass } from '@angular/common';
import {
  QUIZ_MAX_QUESTIONS,
  QUIZ_CHOICES_PER_QUESTION,
  createEmptyQuestion,
} from '../../constants/quiz.constants';

export interface QuizChoiceDraft {
  choice_text: string;
  is_correct: boolean;
}

export interface QuizQuestionDraft {
  question_text: string;
  question_type: 'single';
  choices: QuizChoiceDraft[];
}

@Component({
  selector: 'app-quiz-builder',
  standalone: true,
  imports: [FormsModule, NgClass],
  templateUrl: './quiz-builder.component.html',
  styleUrls: ['./quiz-builder.component.css'],
})
export class QuizBuilderComponent {
  private cdr = inject(ChangeDetectorRef);

  @Input() enabled = false;
  @Input() quizTitle = 'Quiz de présélection';
  @Input() questions: QuizQuestionDraft[] = [];
  @Input() isActive = true;
  @Input() showManageActions = false;
  @Input() showSaveButton = false;
  @Input() hideActivationToggle = false;
  @Input() isSaving = false;

  @Output() enabledChange = new EventEmitter<boolean>();
  @Output() quizTitleChange = new EventEmitter<string>();
  @Output() questionsChange = new EventEmitter<QuizQuestionDraft[]>();
  @Output() isActiveChange = new EventEmitter<boolean>();
  @Output() save = new EventEmitter<void>();
  @Output() toggleVisibility = new EventEmitter<boolean>();

  readonly maxQuestions = QUIZ_MAX_QUESTIONS;
  readonly choicesCount = QUIZ_CHOICES_PER_QUESTION;

  onToggleEnabled(checked: boolean) {
    this.enabledChange.emit(checked);
    if (checked && this.questions.length === 0) {
      this.addQuestion();
    }
    this.cdr.detectChanges();
  }

  addQuestion() {
    if (this.questions.length >= QUIZ_MAX_QUESTIONS) return;
    const next = [...this.questions, createEmptyQuestion()];
    this.questionsChange.emit(next);
    this.cdr.detectChanges();
  }

  removeQuestion(index: number) {
    if (this.questions.length <= 1) return;
    const next = this.questions.filter((_, i) => i !== index);
    this.questionsChange.emit(next);
    this.cdr.detectChanges();
  }

  setCorrectChoice(qIndex: number, cIndex: number) {
    const next = this.questions.map((q, qi) => {
      if (qi !== qIndex) return q;
      return {
        ...q,
        choices: q.choices.map((c, ci) => ({ ...c, is_correct: ci === cIndex })),
      };
    });
    this.questionsChange.emit(next);
    this.cdr.detectChanges();
  }

  updateTitle(value: string) {
    this.quizTitleChange.emit(value);
  }

  validate(): string | null {
    if (!this.enabled) return null;
    if (!this.questions.length) return 'Ajoutez au moins une question.';
    for (let i = 0; i < this.questions.length; i++) {
      const q = this.questions[i];
      if (!q.question_text.trim()) return `La question ${i + 1} est vide.`;
      const filled = q.choices.filter((c) => c.choice_text.trim());
      if (filled.length < QUIZ_CHOICES_PER_QUESTION) {
        return `La question ${i + 1} doit avoir 3 réponses.`;
      }
      if (!q.choices.some((c) => c.is_correct)) {
        return `Indiquez la bonne réponse pour la question ${i + 1}.`;
      }
    }
    return null;
  }

  buildPayload() {
    return {
      title: this.quizTitle.trim() || 'Quiz de présélection',
      questions: this.questions.map((q) => ({
        question_text: q.question_text.trim(),
        question_type: 'single' as const,
        choices: q.choices.map((c) => ({
          choice_text: c.choice_text.trim(),
          is_correct: !!c.is_correct,
        })),
      })),
    };
  }
}
<div class="quiz-builder-card">
  <div class="quiz-builder-header">
    <div>
      <h4><i class="bi bi-patch-question-fill"></i> Quiz de présélection</h4>
      <p>Maximum {{ maxQuestions }} questions · 3 réponses QCM par question · 1 bonne réponse</p>
    </div>
    @if (showManageActions) {
      <span class="quiz-status-pill" [class.active]="isActive" [class.hidden]="!isActive">
        {{ isActive ? 'Visible candidats' : 'Masqué' }}
      </span>
    }
  </div>

  @if (!hideActivationToggle) {
    <label class="quiz-toggle-row" style="margin-bottom: 14px; cursor: pointer;">
      <input type="checkbox" [checked]="enabled" (change)="onToggleEnabled($any($event.target).checked)" />
      <span style="font-size: 14px; font-weight: 600; color: #334155;">Activer un quiz pour cette offre</span>
    </label>
  }

  @if (enabled) {
    <div class="quiz-title-field">
      <label>Titre affiché aux candidats</label>
      <input
        type="text"
        [ngModel]="quizTitle"
        (ngModelChange)="updateTitle($event)"
        name="quizTitleInput"
        placeholder="Ex : Test technique — Développeur Angular"
      />
    </div>

    <p class="quiz-counter">{{ questions.length }} / {{ maxQuestions }} questions</p>

    @for (q of questions; track $index; let qi = $index) {
      <div class="question-card">
        <div class="question-card-header">
          <span class="question-number">Question {{ qi + 1 }}</span>
          @if (questions.length > 1) {
            <button type="button" class="btn-remove-q" (click)="removeQuestion(qi)">Supprimer</button>
          }
        </div>
        <input
          type="text"
          [(ngModel)]="q.question_text"
          [name]="'qb_q_' + qi"
          placeholder="Ex : Quelle est votre expérience avec Angular ?"
        />
        <span class="choices-label">3 réponses — cliquez sur « Bonne réponse »</span>
        @for (c of q.choices; track $index; let ci = $index) {
          <div class="choice-row" [class.correct-selected]="c.is_correct">
            <span style="font-weight: 700; color: #94a3b8; width: 18px;">{{ ['A', 'B', 'C'][ci] }}</span>
            <input
              type="text"
              [(ngModel)]="c.choice_text"
              [name]="'qb_c_' + qi + '_' + ci"
              [placeholder]="'Réponse ' + ['A', 'B', 'C'][ci]"
            />
            <button
              type="button"
              class="btn-mark-correct"
              [class.is-correct]="c.is_correct"
              (click)="setCorrectChoice(qi, ci)"
            >
              {{ c.is_correct ? '✓ Bonne réponse' : 'Marquer correcte' }}
            </button>
          </div>
        }
      </div>
    }

    <button
      type="button"
      class="btn-add-question"
      (click)="addQuestion()"
      [disabled]="questions.length >= maxQuestions"
    >
      + Ajouter une question ({{ questions.length }}/{{ maxQuestions }})
    </button>

    @if (showSaveButton || showManageActions) {
      <div class="quiz-actions-bar">
        <button type="button" class="btn-save-quiz" (click)="save.emit()" [disabled]="isSaving">
          {{ isSaving ? 'Enregistrement…' : 'Enregistrer le quiz' }}
        </button>
        @if (showManageActions) {
          @if (isActive) {
            <button type="button" class="btn-hide-quiz" (click)="toggleVisibility.emit(false)">
              <i class="bi bi-eye-slash"></i> Masquer aux candidats
            </button>
          } @else {
            <button type="button" class="btn-hide-quiz btn-show-quiz" (click)="toggleVisibility.emit(true)">
              <i class="bi bi-eye"></i> Rendre disponible
            </button>
          }
        }
      </div>
    }
  }
</div>
